<?php

declare(strict_types=1);

namespace SqlSemantics\Schema\Column;

use Override;

/**
 * A value supplied by a declared sequence, with an override policy.
 *
 * @visibility public
 * @example Reading an identity column
 *     $column = (new \SqlSemantics\SchemaBuilder(\SqlSemantics\Dialect::PostgreSql))->build('CREATE TABLE t(id INTEGER GENERATED BY DEFAULT AS IDENTITY (START WITH 5 INCREMENT BY 2))')->tables[0]->columns[0];
 *     $column->generation instanceof \SqlSemantics\Schema\Column\IdentityColumn // => true
 *     $column->generation->mode // => \SqlSemantics\Schema\Column\IdentityMode::ByDefault
 *     $column->generation->sequence->start->text // => '5'
 */
final class IdentityColumn implements Generation
{
    /**
     * Constructs a valid declaration.

     */
    public function __construct(
        public readonly IdentityMode $mode,
        public readonly SequenceOptions $sequence = new SequenceOptions(),
    ) {
    }

    /**
     * Returns no generation expression: the identity sequence supplies this column.
     */
    #[Override]
    public function expressions(): array
    {
        return [];
    }
}
